import{_t as e,it as t,n,rt as r}from"./chunks/framework.DFBuBo0J.js";var i=JSON.parse(`{"title":"Algorithm Support","description":"","frontmatter":{"packageVersion":"0.15.0"},"headers":[],"relativePath":"reference/algorithms.md","filePath":"site/versions/v0.15.0/reference/algorithms.md","lastUpdated":0}`),a={name:`reference/algorithms.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="algorithm-support" tabindex="-1">Algorithm Support <a class="header-anchor" href="#algorithm-support" aria-label="Permalink to “Algorithm Support”">​</a></h1><h2 id="signature-algorithms" tabindex="-1">Signature algorithms <a class="header-anchor" href="#signature-algorithms" aria-label="Permalink to “Signature algorithms”">​</a></h2><p>The same set signs and verifies everywhere a signature appears: certificates, CSRs, CRLs, OCSP requests and responses, PKCS#7 SignedData, and detached signatures through <code>micro509/crypto</code> (<code>signData</code> / <code>verifySignature</code>).</p><table tabindex="0"><thead><tr><th>Algorithm</th><th style="text-align:center;">Signing</th><th style="text-align:center;">Verification</th></tr></thead><tbody><tr><td>RSA PKCS#1 v1.5</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>RSA‑PSS</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>ECDSA P‑256</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>ECDSA P‑384</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>ECDSA P‑521</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr><tr><td>Ed25519</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td></tr></tbody></table><h2 id="key-formats" tabindex="-1">Key formats <a class="header-anchor" href="#key-formats" aria-label="Permalink to “Key formats”">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th style="text-align:center;">Import</th><th style="text-align:center;">Export</th><th style="text-align:center;">Encrypted</th></tr></thead><tbody><tr><td>PKCS#8</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">PBES2 (AES‑CBC + PBKDF2)</td></tr><tr><td>SPKI</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">—</td></tr><tr><td>JWK</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">—</td></tr><tr><td>PKCS#1 (RSA)</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">Legacy PEM (AES‑CBC)</td></tr><tr><td>SEC1 (EC)</td><td style="text-align:center;">yes</td><td style="text-align:center;">yes</td><td style="text-align:center;">Legacy PEM (AES‑CBC)</td></tr></tbody></table><h2 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to “Encryption”">​</a></h2><table tabindex="0"><thead><tr><th>Context</th><th>Schemes</th></tr></thead><tbody><tr><td>Encrypted PKCS#8</td><td>PBES2 with AES‑CBC + PBKDF2 HMAC‑SHA1 or HMAC‑SHA256</td></tr><tr><td>Encrypted PFX</td><td>PBES2 with AES‑CBC + PBKDF2 HMAC‑SHA1 or HMAC‑SHA256</td></tr><tr><td>Legacy encrypted PEM</td><td>AES‑128‑CBC, AES‑192‑CBC, AES‑256‑CBC</td></tr><tr><td>PKCS#12 MAC</td><td>PKCS#12 KDF + HMAC‑SHA‑256</td></tr><tr><td>PBMAC1 (<a href="https://www.rfc-editor.org/rfc/rfc9879.html" target="_blank" rel="noreferrer">RFC 9879</a>)</td><td>PBKDF2 HMAC‑SHA‑256/384/512 + HMAC‑SHA‑256/384/512; creation uses SHA‑256</td></tr><tr><td>RSA‑OAEP</td><td>key encapsulation with SHA‑256/384/512 keys and optional label</td></tr></tbody></table><h2 id="not-supported" tabindex="-1">Not supported <a class="header-anchor" href="#not-supported" aria-label="Permalink to “Not supported”">​</a></h2><p>micro509 does not try to mirror every primitive some WebCrypto runtimes expose:</p><ul><li>DSA</li><li>Ed448, X25519, X448 key operations. Certificates carrying them still parse, and <a href="https://www.rfc-editor.org/rfc/rfc9295.html" target="_blank" rel="noreferrer">RFC 9295</a> key-usage rules are enforced for all four safe-curve OIDs</li><li>ECDH and other key agreement</li><li>Generic symmetric-crypto APIs</li><li>Brainpool curves</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};